// Automaattisesti generoitu dwilloflute-soundfont abcjs:lle
if (typeof window !== 'undefined') {
    if (!window.WebAudioFontInstrumentCollection) window.WebAudioFontInstrumentCollection = {};
    window.WebAudioFontInstrumentCollection['dwilloflute'] = {
        zone: [
            {
                midi: 73,
                originalPitch: 7300,
                sampleRate: 44100,
                loopStart: 0,
                loopEnd: 0,
                ahdsr: true,
                file: ""
            }
        ]
    };
}
